create table if not exists public.price_list(price_list_id bigint generated always as identity primary key,list_name text not null,subsidiary_id bigint not null references public.subsidiaries(subsidiary_id),currency_id bigint not null references public.currencies(currency_id),is_active boolean not null default true,unique(list_name,subsidiary_id,currency_id));
create table if not exists public.price_list_item(id bigint generated always as identity primary key,price_list_id bigint not null references public.price_list(price_list_id) on delete cascade,product_id bigint not null references public.products(product_id) on delete cascade,uom_id bigint not null references public.uom(uom_id),unit_price numeric(24,6) not null check(unit_price>=0),min_quantity numeric(24,6) not null default 1 check(min_quantity>0),unique(price_list_id,product_id,uom_id,min_quantity));
do $$declare t text;begin foreach t in array array['price_list','price_list_item']loop execute format('alter table public.%I enable row level security',t);execute format('drop policy if exists "sales_select" on public.%I',t);execute format('drop policy if exists "sales_insert" on public.%I',t);execute format('drop policy if exists "sales_update" on public.%I',t);execute format('drop policy if exists "sales_delete" on public.%I',t);execute format('create policy "sales_select" on public.%I for select to authenticated using(true)',t);execute format('create policy "sales_insert" on public.%I for insert to authenticated with check(true)',t);execute format('create policy "sales_update" on public.%I for update to authenticated using(true) with check(true)',t);execute format('create policy "sales_delete" on public.%I for delete to authenticated using(true)',t);end loop;end$$;
